{"policy":"permit (
    principal is User,
    action == Action::"approveChange",
    resource is ChangeRequest
)
when {
    (principal.isChangeManager || principal.isCabApprover) &&
    (
        (resource.estimatedCost.greaterThanOrEqual(context.cabSignoffCostThreshold) && principal.isCabApprover) ||
        (resource.estimatedCost.lessThan(context.cabSignoffCostThreshold) && principal.grantedChangeAuthorityLevel >= resource.assessedRisk)
    )
};

forbid (
    principal is User,
    action == Action::"approveChange",
    resource is ChangeRequest
)
when {
    resource.estimatedCost.lessThan(context.cabSignoffCostThreshold) &&
    resource.assessedRisk > principal.grantedChangeAuthorityLevel
};

permit (
    principal is User,
    action == Action::"implementChange",
    resource is ChangeRequest
)
when {
    principal.isNetworkEngineer &&
    resource.currentStatus == ChangeStatus::"Approved" &&
    (resource.isEmergency || context.currentTime.greaterThanOrEqual(resource.maintenanceWindowStart))
};

forbid (
    principal is User,
    action == Action::"implementChange",
    resource is ChangeRequest
)
when {
    resource.currentStatus != ChangeStatus::"Approved"
};"}
